  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.07, 2.2, 0.8],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*60, 0.09, 1.8, 1.0],
