    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 1.1],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.82+2)*75, 0.065, 2.8, 0.7],
