    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.2)*w;
    aS2 += Math.sin(d2*f*1.3 - t*sp*0.7 + 0.5)*w;
    iS2 += Math.cos(d2*f*0.9 + t*sp*0.8)*w;
