  const tw = 7.4;
  const act = aS/tw, inh = iS/tw, act2 = aS2/tw, inh2 = iS2/tw;
  const bg = (Math.sin(sx*0.035+sy*0.02+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
